import React, { useCallback, useRef, useState } from 'react';
import { Link } from 'react-router-dom';
import { Action } from '@thoughtspot/visual-embed-sdk';
import { LiveboardEmbed, SpotterMessage, useSpotterAgent } from '@thoughtspot/visual-embed-sdk/react';
import { THOUGHTSPOT_LIVEBOARD_ID, THOUGHTSPOT_MODEL_ID } from '../config/thoughtspot';
import { useTier } from '../config/TierContext';

const vizIds = [
  '0fec93cd-2914-4a54-bb53-38e5ba74b96b',
  'c733de69-fe92-47df-891c-d774635cbfa3',
  'da90af4a-ed6e-454a-bc8f-2a9b818e2d0a',
];

function VizTile({ vizId, hiddenActions, disabledActions }: {
  vizId: string;
  hiddenActions: Action[];
  disabledActions: Action[];
}) {
  const [embedError, setEmbedError] = useState<string | null>(null);

  const onError = useCallback((err: { data?: { errorMessage?: string }; message?: string }) => {
    const msg =
      err?.data?.errorMessage ||
      err?.message ||
      (typeof err === 'object' ? JSON.stringify(err) : String(err));
    setEmbedError(msg);
    console.error('[ThoughtSpot Viz]', err);
  }, []);

  return (
    <div
      style={{
        backgroundColor: '#ffffff',
        borderRadius: 12,
        border: '1px solid #E5E7EB',
        overflow: 'hidden',
        height: 300,
      }}
    >
      {embedError ? (
        <div
          role="alert"
          style={{
            margin: '1rem',
            padding: '0.75rem 1rem',
            background: '#FEF2F2',
            border: '1px solid #FECACA',
            borderRadius: 8,
            fontSize: 13,
            color: '#991B1B',
          }}
        >
          <strong>Error:</strong> {embedError}
        </div>
      ) : (
        <div
          style={{
            width: '200%',
            height: 600,
            transform: 'scale(0.5)',
            transformOrigin: 'top left',
          }}
        >
          <LiveboardEmbed
            liveboardId={THOUGHTSPOT_LIVEBOARD_ID}
            vizId={vizId}
            hiddenActions={hiddenActions}
            disabledActions={disabledActions}
            onError={onError}
            isLiveboardStylingAndGroupingEnabled={true}
            additionalFlags={{ enable2ColumnLayout: true }}
            style={{ width: '100%', height: '100%' }}
          />
        </div>
      )}
    </div>
  );
}

type ChatMessage = { role: 'user'; text: string } | { role: 'ai'; message: any };

function SpotterChatBubble() {
  const [open, setOpen] = useState(false);
  const [input, setInput] = useState('');
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [loading, setLoading] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const { sendMessage } = useSpotterAgent({ worksheetId: THOUGHTSPOT_MODEL_ID });

  const handleSend = async () => {
    const query = input.trim();
    if (!query || loading) return;
    setInput('');
    setMessages(prev => [...prev, { role: 'user', text: query }]);
    setLoading(true);
    try {
      const result = await sendMessage(query);
      setMessages(prev => [...prev, { role: 'ai', message: result.message }]);
    } finally {
      setLoading(false);
      setTimeout(() => messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' }), 50);
    }
  };

  return (
    <>
      {open && (
        <div style={{
          position: 'fixed', bottom: 80, right: 24, width: 420,
          backgroundColor: '#fff', borderRadius: 16,
          border: '1px solid #E5E7EB', zIndex: 300,
          display: 'flex', flexDirection: 'column', overflow: 'hidden',
        }}>
          <div style={{
            padding: '14px 16px', backgroundColor: '#ffffff',
            borderBottom: '1px solid #F3F4F6',
            display: 'flex', alignItems: 'center', justifyContent: 'space-between',
          }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
              <div style={{ width: 28, height: 28, borderRadius: '50%', backgroundColor: '#EDE9FE', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                <svg width="14" height="14" viewBox="0 0 18 18" fill="none">
                  <circle cx="9" cy="9" r="7" stroke="#7C3AED" strokeWidth="1.5"/>
                  <circle cx="9" cy="9" r="3" fill="#7C3AED"/>
                </svg>
              </div>
              <span style={{ color: '#111827', fontWeight: 700, fontSize: 14 }}>JETT <span style={{ color: '#7C3AED' }}>AI</span></span>
            </div>
            <button onClick={() => setOpen(false)} style={{
              background: 'none', border: 'none', color: '#9CA3AF',
              cursor: 'pointer', fontSize: 18, lineHeight: 1, padding: 0,
            }}>×</button>
          </div>

          <div style={{
            flex: 1, overflowY: 'auto', padding: '12px 16px',
            display: 'flex', flexDirection: 'column', gap: 12, maxHeight: 820,
            minHeight: 200, backgroundColor: '#FAFAFA',
          }}>
            {messages.length === 0 && (
              <p style={{ color: '#9CA3AF', fontSize: 13, margin: 0, textAlign: 'center', paddingTop: 16 }}>
                Ask a question about your travel data
              </p>
            )}
            {messages.map((msg, i) =>
              msg.role === 'user' ? (
                <div key={i} style={{
                  alignSelf: 'flex-end', backgroundColor: '#7C3AED',
                  color: '#fff', borderRadius: 12, padding: '8px 12px',
                  fontSize: 13, maxWidth: '80%',
                }}>{msg.text}</div>
              ) : (
                <div key={i} style={{ alignSelf: 'flex-start', width: '125%', transform: 'scale(0.8)', transformOrigin: 'top left' }}>
                  <SpotterMessage message={msg.message} style={{ width: '100%', height: '280px' }} />
                </div>
              )
            )}
            {loading && (
              <div style={{ color: '#9CA3AF', fontSize: 13, fontStyle: 'italic' }}>Thinking…</div>
            )}
            <div ref={messagesEndRef} />
          </div>

          <div style={{
            padding: '10px 12px', borderTop: '1px solid #F3F4F6',
            display: 'flex', gap: 8, backgroundColor: '#fff',
          }}>
            <input
              value={input}
              onChange={e => setInput(e.target.value)}
              onKeyDown={e => e.key === 'Enter' && handleSend()}
              placeholder="Ask about your travel data…"
              style={{
                flex: 1, border: '1px solid #E5E7EB', borderRadius: 8,
                padding: '8px 12px', fontSize: 13, outline: 'none',
                backgroundColor: '#F9FAFB', color: '#111827',
              }}
            />
            <button onClick={handleSend} disabled={loading || !input.trim()} style={{
              backgroundColor: '#7C3AED', color: '#fff', border: 'none',
              borderRadius: 8, padding: '8px 14px', fontSize: 13,
              fontWeight: 600, cursor: 'pointer', opacity: loading || !input.trim() ? 0.5 : 1,
            }}>Send</button>
          </div>
        </div>
      )}

      <button
        onClick={() => setOpen(o => !o)}
        style={{
          position: 'fixed', bottom: 24, right: 24,
          backgroundColor: '#7C3AED', color: '#fff', border: 'none',
          display: 'flex', alignItems: 'center', gap: 8,
          padding: '11px 20px', borderRadius: 28, fontSize: 14,
          fontWeight: 600, cursor: 'pointer',
          zIndex: 200,
        }}
      >
        <svg width="16" height="16" viewBox="0 0 18 18" fill="none">
          <path d="M3 3h12v9H6l-3 3V3z" stroke="#fff" strokeWidth="1.5" strokeLinejoin="round"/>
        </svg>
        Ask JETT AI
        <span style={{ width: 7, height: 7, borderRadius: '50%', backgroundColor: '#10B981', display: 'inline-block' }} />
      </button>
    </>
  );
}

export default function LandingPage() {
  const { hiddenActions, disabledActions, spotterEnabled, tier } = useTier();

  return (
    <div style={{ minHeight: '100vh', backgroundColor: '#F7F6FF' }}>
      {/* Page header */}
      <div style={{ padding: '2rem 2.5rem 0' }}>
        <div style={{ display: 'flex', alignItems: 'flex-start', justifyContent: 'space-between' }}>
          <div>
            <h1 style={{ fontSize: 26, fontWeight: 700, color: '#111827', margin: 0 }}>
              Travel Overview
            </h1>
            <p style={{ fontSize: 13.5, color: '#6B7280', margin: '4px 0 0' }}>
              Key performance metrics across your travel programme
            </p>
          </div>
          <div
            style={{
              display: 'flex',
              alignItems: 'center',
              gap: 6,
              border: '1px solid #E5E7EB',
              borderRadius: 20,
              padding: '5px 12px',
              backgroundColor: '#fff',
            }}
          >
            <span style={{ width: 7, height: 7, borderRadius: '50%', backgroundColor: '#10B981', display: 'inline-block' }} />
            <span style={{ fontSize: 12.5, fontWeight: 600, color: '#374151' }}>LIVE</span>
          </div>
        </div>
      </div>

      {/* Welcome card */}
      <div style={{ padding: '1.25rem 2.5rem' }}>
        <div
          style={{
            backgroundColor: '#ffffff',
            borderRadius: 12,
            padding: '1.5rem 1.75rem',
            borderLeft: '4px solid #7C3AED',
            border: '1px solid #E5E7EB',
            borderLeftWidth: 4,
            borderLeftColor: '#7C3AED',
          }}
        >
          <p style={{ fontSize: 13, color: '#9CA3AF', margin: 0 }}>Welcome back,</p>
          <h2 style={{ fontSize: 22, fontWeight: 700, color: '#7C3AED', margin: '3px 0 6px' }}>
            JETT Analytics
          </h2>
          <p style={{ fontSize: 13.5, color: '#6B7280', margin: 0 }}>
            Here's an overview of your latest travel insights. You're on the <strong style={{ color: '#111827' }}>{tier}</strong> tier.
          </p>
        </div>
      </div>

      {/* Viz tiles */}
      <div style={{ padding: '0 2.5rem 1.25rem' }}>
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: '1rem' }}>
          {vizIds.map((id) => (
            <VizTile key={id} vizId={id} hiddenActions={hiddenActions} disabledActions={disabledActions} />
          ))}
        </div>
      </div>

      {/* Quick access cards */}
      <div style={{ padding: '0 2.5rem 2rem' }}>
        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr 1fr', gap: '1rem' }}>

          {/* Analytics Dashboard card */}
          <Link
            to="/dashboard"
            style={{
              textDecoration: 'none',
              backgroundColor: '#ffffff',
              borderRadius: 12,
              padding: '1.5rem',
              display: 'flex',
              alignItems: 'center',
              gap: 14,
              border: '1px solid #E5E7EB',
              transition: 'border-color 0.15s ease',
            }}
          >
            <div
              style={{
                width: 42,
                height: 42,
                backgroundColor: '#EDE9FE',
                borderRadius: 10,
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                flexShrink: 0,
              }}
            >
              <svg width="20" height="20" viewBox="0 0 18 18" fill="none">
                <rect x="2" y="9" width="3.5" height="7" rx="1" stroke="#7C3AED" strokeWidth="1.5"/>
                <rect x="7.25" y="5" width="3.5" height="11" rx="1" stroke="#7C3AED" strokeWidth="1.5"/>
                <rect x="12.5" y="2" width="3.5" height="14" rx="1" stroke="#7C3AED" strokeWidth="1.5"/>
              </svg>
            </div>
            <div>
              <div style={{ color: '#111827', fontWeight: 600, fontSize: 14 }}>Analytics Dashboard</div>
              <div style={{ color: '#9CA3AF', fontSize: 12, marginTop: 2 }}>View detailed liveboard</div>
            </div>
          </Link>

          {/* JETT AI card */}
          <Link
            to="/spotter"
            style={{
              textDecoration: 'none',
              backgroundColor: spotterEnabled ? '#7C3AED' : '#ffffff',
              borderRadius: 12,
              padding: '1.5rem',
              display: 'flex',
              alignItems: 'center',
              gap: 14,
              border: spotterEnabled ? '1px solid #7C3AED' : '1px solid #E5E7EB',
              position: 'relative',
              overflow: 'hidden',
            }}
          >
            <div
              style={{
                width: 42,
                height: 42,
                backgroundColor: spotterEnabled ? 'rgba(255,255,255,0.2)' : '#EDE9FE',
                borderRadius: 10,
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                flexShrink: 0,
              }}
            >
              <svg width="20" height="20" viewBox="0 0 18 18" fill="none">
                <circle cx="9" cy="9" r="7" stroke={spotterEnabled ? '#fff' : '#7C3AED'} strokeWidth="1.5"/>
                <circle cx="9" cy="9" r="3" fill={spotterEnabled ? '#fff' : '#7C3AED'}/>
              </svg>
            </div>
            <div>
              <div style={{ color: spotterEnabled ? '#fff' : '#111827', fontWeight: 600, fontSize: 14 }}>JETT AI</div>
              <div style={{ color: spotterEnabled ? 'rgba(255,255,255,0.75)' : '#9CA3AF', fontSize: 12, marginTop: 2 }}>
                {spotterEnabled ? 'Ask questions with JETT AI' : 'Upgrade to Pro to unlock'}
              </div>
            </div>
            {!spotterEnabled && (
              <span style={{
                position: 'absolute', top: 12, right: 12,
                fontSize: 9, fontWeight: 700,
                backgroundColor: '#EDE9FE', color: '#7C3AED',
                padding: '2px 7px', borderRadius: 4,
                letterSpacing: '0.5px', textTransform: 'uppercase',
              }}>PRO</span>
            )}
          </Link>

          {/* Reports card */}
          <Link
            to="/reports"
            style={{
              textDecoration: 'none',
              backgroundColor: '#ffffff',
              borderRadius: 12,
              padding: '1.5rem',
              display: 'flex',
              alignItems: 'center',
              gap: 14,
              border: '1px solid #E5E7EB',
            }}
          >
            <div
              style={{
                width: 42,
                height: 42,
                backgroundColor: '#F3F4F6',
                borderRadius: 10,
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                flexShrink: 0,
              }}
            >
              <svg width="20" height="20" viewBox="0 0 18 18" fill="none">
                <rect x="3" y="1" width="12" height="16" rx="2" stroke="#6B7280" strokeWidth="1.5"/>
                <line x1="6" y1="5.5" x2="12" y2="5.5" stroke="#6B7280" strokeWidth="1.5"/>
                <line x1="6" y1="9" x2="12" y2="9" stroke="#6B7280" strokeWidth="1.5"/>
                <line x1="6" y1="12.5" x2="10" y2="12.5" stroke="#6B7280" strokeWidth="1.5"/>
              </svg>
            </div>
            <div>
              <div style={{ color: '#111827', fontWeight: 600, fontSize: 14 }}>Reports</div>
              <div style={{ color: '#9CA3AF', fontSize: 12, marginTop: 2 }}>Saved reports &amp; exports</div>
            </div>
          </Link>
        </div>
      </div>

      {/* JETT AI floating chat bubble */}
      {spotterEnabled ? <SpotterChatBubble /> : (
        <Link
          to="/spotter"
          style={{
            position: 'fixed', bottom: 24, right: 24,
            backgroundColor: '#9CA3AF', color: '#fff', textDecoration: 'none',
            display: 'flex', alignItems: 'center', gap: 8,
            padding: '11px 20px', borderRadius: 28, fontSize: 14, fontWeight: 600,
            zIndex: 200,
          }}
        >
          <svg width="16" height="16" viewBox="0 0 18 18" fill="none">
            <path d="M3 3h12v9H6l-3 3V3z" stroke="#fff" strokeWidth="1.5" strokeLinejoin="round"/>
          </svg>
          JETT AI (Pro)
          <span style={{ width: 7, height: 7, borderRadius: '50%', backgroundColor: '#D1D5DB', display: 'inline-block' }} />
        </Link>
      )}
    </div>
  );
